     1→using DayZ;
     2→using System;
     3→using System.Collections.Generic;
     4→using UnityEngine;
     5→
     6→namespace DayZ
     7→{
     8→    /// <summary>
     9→    /// 用于小游戏获取基础数据
    10→    /// </summary>
    11→    public class BaseGameManager : IBaseGameManager, IManager
    12→    {
    13→        /// <summary>
    14→        /// 攻击、防御、生命
    15→        /// </summary>
    16→        /// <param name="heroId"></param>
    17→        /// <param name="attr"></param>
    18→        /// <returns></returns>
    19→        public double GetHeroAttr(string heroId, SnowHeroAttrType attr)
    20→        {
    21→            HeroInfoData m_heroData = FreeBuildHeroController.getInstance().getHeroInfoData(heroId);
    22→            int heroLv = m_heroData.getHeroLevel() - 1;
    23→            var starSkillAdd = m_heroData.getStarSkillAddProp(m_heroData.getHeroStar());
    24→
    25→            if (attr == SnowHeroAttrType.hero_atk)
    26→            {
    27→                return (m_heroData.attributesInfo.attack[heroLv] +
    28→                    m_heroData.m_heroInfo.attrAllDict[SnowHeroAttrType.hero_atk].attrValue +
    29→                    starSkillAdd[1]);
    30→            }
    31→            else if (attr == SnowHeroAttrType.hero_def)
    32→            {
    33→                return (m_heroData.attributesInfo.defense[heroLv] +
    34→                m_heroData.m_heroInfo.attrAllDict[SnowHeroAttrType.hero_def].attrValue +
    35→                starSkillAdd[2]);
    36→            }
    37→            else if (attr == SnowHeroAttrType.hero_hp)
    38→            {
    39→                return (m_heroData.attributesInfo.hitPoints[heroLv] +
    40→                m_heroData.m_heroInfo.attrAllDict[SnowHeroAttrType.hero_hp].attrValue +
    41→                starSkillAdd[3]);
    42→            }
    43→            else if (attr == SnowHeroAttrType.Power)
    44→            {
    45→                return FreeBuildHeroController.getInstance().GetHeroPower(m_heroData.m_heroInfo, heroLv);
    46→            }
    47→            else
    48→            {
    49→                LogCommon.LogError("待补充！！！ 找FFH");
    50→                return m_heroData.getAttrAll(attr);
    51→            }
    52→        }
    53→
    54→        public int GetHeroLevel(string heroId)
    55→        {
    56→            HeroInfoData heroInfoData = FreeBuildHeroController.getInstance().getHeroInfoData(heroId);
    57→            return heroInfoData.getHeroLevel();
    58→        }
    59→
    60→        public int GetHeroStarLevel(string heroId)
    61→        {
    62→            HeroInfoData heroInfoData = FreeBuildHeroController.getInstance().getHeroInfoData(heroId);
    63→            return heroInfoData.getHeroStar();
    64→        }
    65→
    66→        public int GetSkillLevel(string heroId, string skillId)
    67→        {
    68→            var heroInfoData = FreeBuildHeroController.getInstance().getHeroInfoData(heroId);
    69→            var skillGroove = heroInfoData.getSkillInfoById(skillId);
    70→            if (skillGroove != null)
    71→                return skillGroove.getLevel();
    72→            else
    73→                return 0;
    74→        }
    75→
    76→        public int GetSpecialEquipLevel(string heroId)
    77→        {
    78→            var heroInfoData = FreeBuildHeroController.getInstance().getHeroInfoData(heroId);
    79→            var equipInfo = heroInfoData.getSpecialEquipInfo();
    80→            if (equipInfo != null)
    81→                return equipInfo.getUpgradelevel();
    82→            else
    83→                return 0;
    84→        }
    85→
    86→        public void Init()
    87→        {
    88→        }
    89→
    90→        public void OnTick(float t)
    91→        {
    92→        }
    93→
    94→        public void Reset()
    95→        {
    96→        }
    97→    }
    98→}
