    17→    public static CCLayer create(string typeName)
    18→    {
    19→        try
    20→        {
    21→            var st = Type.GetType(typeName);
    22→            if (st != null)
    23→            {
    24→                var mc = st.GetMethod("create", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static);
    25→                if (mc != null)
    26→                {
    27→                    var cLayer = mc.Invoke(null,null) as CCLayer;
    28→                    return cLayer;
    29→                }
    30→            }
    31→
    32→        }
    33→        catch(Exception e)
    34→        {
    35→            LogCommon.LogException(e, "GameSceneLayer");
    36→        }
    37→        
    38→        return null;
    39→    }
    40→}
