     5→{
     6→    public class BindableProperty<T> where T:IEquatable<T>
     7→    {
     8→        private T _value = default(T);
     9→
    10→        public T Value
    11→        {
    12→            get
    13→            {
    14→                return _value;
    15→            }
    16→            set
    17→            {
    18→                if (!_value.Equals(value))
    19→                {
    20→                    _value = value;
    21→                    onValueChanged?.Invoke(value);
    22→                }
    23→            }
    24→        }
    25→
    26→        public Action<T> onValueChanged;
    27→    }
    28→}
