     1→using System;
     2→using UnityEngine;
     3→namespace DayZ.KingShot
     4→{
     5→    public class KingShotManager : IKingShotManager, IManager
     6→    {
     7→        public static KingShotManager Instance { get; private set; }
     8→        public GameObject SceneObj { get; private set; }
     9→        public string SceneId { get; private set; }
    10→        public bool IsEnterGame { get; private set; } = false;
    11→        public MiniGameData GameData { get; private set; }
    12→        public KingShotGameType GameType { get; private set; }
    13→        private float shadowDis = 0;
    14→        private Material oldSkybox;
    15→        public void Init()
    16→        {
    17→        }
    18→        public void OnTick(float t)
    19→        {
    20→        }
    21→        public void Reset()
    22→        {
    23→            LeaveGame(false);
    24→        }
    25→        public void EnterGame(string sceneId, KingShotGameType gameType, MiniGameData gameData = null)
    26→        {
    27→            if (SceneObj == null)
    28→            {
    29→                Instance = this;
    30→                shadowDis = QualitySettings.shadowDistance;
    31→                //QualitySettings.shadowDistance = 0;
    32→                oldSkybox = RenderSettings.skybox;
    33→                SceneId = sceneId;
    34→                this.GameData = gameData != null ? gameData : new MiniGameData("");
    35→                GameType = gameType;
    36→                if (GameType == KingShotGameType.None)
    37→                    KingShotSelectLevelView.Create((config) =>
    38→                    {
    39→                        Global.POST_SAFE_NOTIFY(GameConfig.KINGSHOT_MSG_EnterLevelGame);
    40→                        LoadScene(config.id);
    41→                    });
    42→                else
    43→                {
    44→                    Global.POST_SAFE_NOTIFY(GameConfig.KINGSHOT_MSG_EnterLevelGame);
    45→                    LoadScene(sceneId);
    46→                }
    47→            }
    48→        }
    49→        public void LeaveGame(bool reset, Action callback = null)
    50→        {
    51→            if (Instance != null)
    52→            {
    53→                Time.timeScale = 1;
    54→                QualitySettings.shadowDistance = shadowDis;
    55→                RenderSettings.skybox = oldSkybox;
    56→                CloseAllPopupViews();
    57→                ClearAll();
    58→                Instance = null;
    59→                if (!reset)
    60→                {
    61→                    Global.POST_SAFE_NOTIFY(GameConfig.KINGSHOT_MSG_LeaveLevelGame);
    62→                    GotoSceneBack(callback);
    63→                }
    64→            }
    65→            SoundController.sharedSound().stopAllMusic();
    66→            SoundController.sharedSound().stopAllEffects();
    67→            SoundController.sharedSound().playMainSceneBGMusic();
    68→        }
    69→        private void GotoSceneBack(Action callback = null)
    70→        {
    71→            switch (GameType)
    72→            {
    73→                case KingShotGameType.Battle:
    74→                    callback?.Invoke();
    75→                    break;
    76→                default:
    77→                    callback?.Invoke();
    78→                    break;
    79→            }
    80→        }
    81→        public void ResetGame()
    82→        {
    83→            LeaveGame(true);
    84→            EnterGame(SceneId, GameType, GameData);
    85→        }
    86→        private void LoadScene(string id)
    87→        {
    88→            SoundController.sharedSound().stopAllMusic();
    89→            SoundController.sharedSound().stopAllEffects();
    90→
    91→            SceneObj = CCNodeCache.Instance.GetGameObject("Game/KingShot/Scenes/Scene",
    92→                new Vector3(500, 0, 0), Vector3.zero);
    93→            SceneObj.transform.parent = null;
    94→
    95→            var SceneLogic = SceneObj.AddComponentSafe<GameLogic>();
    96→            if (SceneLogic.PlayerManager == null)
    97→                SceneLogic.PlayerManager = new PlayerManager();
    98→
    99→            GameManager.Instance.Init(GameRunType.Level, SceneLogic);
   100→
   101→            GameManager.Instance.ChangeSkyBox();
   102→            var config = GameConfig.GetDataWithTypeById<Shot_adventureLevel>(id);
   103→            GameManager.Instance.InitGame(config, null);
   104→            if (GameManager.Instance.herolevelType == ELevelType.Soldier)
   105→            {
   106→                ShowMainUI();
   107→            }
   108→            else
   109→            {
   110→                KingShotFormationView.create();
   111→            }
   112→        }
   113→        public void ShowMainUI()
   114→        {
   115→            GameManager.Instance.StartBattle(() =>
   116→            {
   117→                KingShotBattleView.Create();
   118→            });
   119→
   120→        }
   121→        /// <summary>
   122→        /// 关闭全部UI界面
   123→        /// state ： 0 全部UI 1 保留KingShot主UI不关闭
   124→        /// </summary>
   125→        /// <param name="state"></param>
   126→        public static void CloseAllPopupViews(int state = 0)
   127→        {
   128→            var views = PopupViewController.getInstance().GetAllPopupViews();
   129→            foreach (var view in views)
   130→            {
   131→                if (state == 0 || (state == 1 && !view.Contains("KingShotMainView") && !view.Contains("KingShotJoyStick")))
   132→                {
   133→                    PopupViewController.getInstance().ClosePopupView(view);
   134→                }
   135→            }
   136→        }
   137→        private void ClearAll()
   138→        {
   139→            if (SceneObj != null)
   140→            {
   141→                GameManager.Instance.ClearAll();
   142→                CCNodeCache.Instance.DestroyGameObject(SceneObj, "Game/KingShot/Scenes/Scene");
   143→                SceneObj = null;
   144→                Debug.LogError("KingShotManager Clear All");
   145→            }
   146→        }
   147→    }
   148→}
