     6→{
     7→    public class KingShotScene : CCLayer
     8→    {
     9→        protected static KingShotScene instance = null;
    10→        public GameObject SceneObj { get; private set; }
    11→        private SceneLogic SceneLogic;
    12→        public static KingShotScene Instance
    13→        {
    14→            get
    15→            {
    16→                return instance;
    17→            }
    18→        }
    19→        private Shot_scene CurConfig;
    20→        public new static KingShotScene create()
    21→        {
    22→            try
    23→            {
    24→                if (instance != null)
    25→                {
    26→                    Destroy(instance.gameObject);
    27→                    instance = null;
    28→                }
    29→                var result = createPrototype<KingShotScene>();
    30→                result.init();
    31→                result.setVisible(true);
    32→                return result;
    33→            }
    34→            catch (System.Exception e)
    35→            {
    36→                LogCommon.LogException(e, "KingShotScene");
    37→            }
    38→            return null;
    39→        }
    40→        protected override bool init()
    41→        {
    42→            if (!base.init())
    43→                return false;
    44→            instance = this;
    45→            return true;
    46→        }
    47→        public void CreateUI()
    48→        {
    49→            if (!ArchivedData.Instance.LocalRecord)
    50→                KingShotLevelView.Create(EnterGame);
    51→            else
    52→                KingShotLevelView.Create(StartGame);
    53→        }
    54→        private void EnterGame(Shot_scene config)
    55→        {
    56→            KSSceneOperateCommand cmd = new KSSceneOperateCommand(config.id);
    57→            cmd.setSuccessCallback((NetResult ret) =>
    58→            {
    59→                StartGame(config);
    60→            });
    61→            cmd.send();
    62→        }
    63→        public override void cleanup()
    64→        {
    65→            base.cleanup();
    66→            this.clearAll();
    67→        }
    68→        private void clearAll()
    69→        {
    70→            if (SceneObj != null)
    71→            {
    72→                GameManager.Instance.ClearAll();
    73→                CCNodeCache.Instance.DestroyGameObject(SceneObj, CurConfig.model);
    74→                SceneObj = null;
    75→            }
    76→        }
    77→        public void StartGame(string sceneId)
    78→        {
    79→            var config = GameConfig.GetDataWithTypeById<Shot_scene>(sceneId);
    80→            if (config != null)
    81→                StartGame(config);
    82→        }
    83→        public void StartGame(Shot_scene config)
    84→        {
    85→            cleanup();
    86→            CurConfig = config;
    87→            PopupViewController.getInstance().removeAllPopupView();
    88→            LoadScene(config.id, 0);
    89→        }
    90→        private void LoadScene(string id, int TypeId)
    91→        {
    92→            LogCommon.LogError("LoadScene:" + id);
    93→            SoundController.sharedSound().stopAllMusic();
    94→            var config = DataAtlasManager.Instance.GetDataWithTypeById<Shot_scene>(id);
    95→            if (config == null)
    96→            {
    97→                LogCommon.LogError($"Shot_scene表,id:{id}的配置不存在");
    98→                return;
    99→            }
   100→            if (config.model == "")
   101→            {
   102→                LogCommon.LogError($"Shot_scene表,id:{id}的model字段填写错误");
   103→                return;
   104→            }
   105→            var obj = CCNodeCache.Instance.GetGameObject(config.model);
   106→            if (obj == null)
   107→            {
   108→                LogCommon.LogError($"Shot_scene表,id:{id}的model字段{config.model}的预制体不存在");
   109→                return;
   110→            }
   111→            obj.transform.SetParent(this.transform);
   112→            SceneObj = obj;
   113→            SceneLogic = SceneObj.AddComponentSafe<SceneLogic>();
   114→            if (SceneLogic.PlayerManager == null)
   115→                SceneLogic.PlayerManager = new PlayerManager();
   116→
   117→            GameManager.Instance.Init(GameRunType.YKFLevel, SceneLogic);
   118→            KingShotJoyStick.Create();
   119→            GameManager.Instance.InitGame(config, null);
   120→            SetCameraFollow(true);
   121→
   122→            StartBattle();
   123→        }
   124→        public void SetCameraFollow(bool isfollow)
   125→        {
   126→            var CameraFollow = SceneObj.GetComponentInChildren<Cinemachine.CinemachineVirtualCamera>();
   127→            if (CameraFollow != null)
   128→            {
   129→                if (isfollow)
   130→                {
   131→                    var follow = GameManager.Instance.BaseLogic.PlayerManager.lordHero.transform.Find("CameraPos/CameraRecoil");
   132→                    CameraFollow.Follow = follow;
   133→                    CameraFollow.LookAt = follow;
