   625→        public virtual bool isShowLight()
   626→        {
   627→            // 如果为白天直接返回false
   628→            if (CCCommonUtils.isFreeNightTime() == false)
   629→            {
   630→                return false;
   631→            }
   632→
   633→            // 电没有解锁
   634→            if (ResourceController.getInstance().isResUnLocked((int)WorldResourceType.Electricity) == false)
   635→            {
   636→                return false;
   637→            }
   638→
   639→            // 如果缺点也不进行夜景处理！
   640→            if (ResourceController.getInstance().isInLackStateByResType((int)WorldResourceType.Electricity))
   641→            {
   642→                return false;
   643→            }
   644→
   645→            // 如果没有夜景建筑的话
   646→            if (!FunBuildController.isExistBuildLight(m_buildingKey / 1000))
   647→            {
   648→                return false;
   649→            }
   650→
   651→            var info = getFunBuildInfo();
   652→            if (info == null)
   653→            {
   654→                return false;
   655→            }
   656→
   657→            // 如果是废墟状态，也不显示灯光了
   658→            if (info.level < 1)
   659→            {
   660→                return false;
   661→            }
   662→
   663→            if (info.getConnected() == false)
   664→            {
   665→                return false;
   666→            }
   667→
   668→            if (info.state != Global.FUN_BUILD_NORMAL)
   669→            {
   670→                return false;
   671→            }
   672→
   673→            return true;
   674→        }
