   249→        /// <summary>
   250→        /// 防守关卡的胜利条件
   251→        /// </summary>
   252→        /// <param name="o"></param>
   253→        private void CheckGameOver(object o)
   254→        {
   255→            if (isGameOver || !IsStartGame())
   256→                return;
   257→            result = -1;
   258→            if (GameType == GameRunType.Scene)
   259→            {
   260→                if (BaseLogic.PlayerManager.MainBuildingIsDead())
   261→                    result = 1;
   262→            }
   263→            else if (GameType == GameRunType.YKFLevel)
   264→            {
   265→                if (BaseLogic.PlayerManager.lordHero.IsDead)
   266→                    result = 1;
   267→            }
   268→            else
   269→            {
   270→                if (BaseLogic.PlayerManager.mPlayers.Count == 0)
   271→                    result = 1;
   272→            }
   273→            if (GameType != GameRunType.YKFLevel && BaseLogic.PlayerManager.MonsterNum == 0)
   274→                result = 0;
   275→            if (result > -1)
   276→            {
   277→                isGameOver = true;
   278→                if (result == 1)
   279→                {
   280→                    Scheduler.Instance.scheduleOnce((f) =>
   281→                    {
   282→                        BattleOver(result);
   283→                    }, 0.1f, this);
   284→                }
   285→                else if (result == 0)
   286→                {
   287→                    Global.POST_SAFE_NOTIFY(GameConfig.KINGSHOT_MSG_SUCCESS_Run);
   288→                    Scheduler.Instance.scheduleOnce((f) =>
   289→                    {
   290→                        BattleOver(result);
   291→                    }, playerMoveTime, this);
   292→                }
   293→            }
   294→        }
