   315→        /// <summary>
   316→        /// 战力检查
   317→        /// </summary>
   318→        public EFighting CheckAtk()
   319→        {
   320→            PVEJoinerInfo atker = PVEController.Instance.GetPveAttackInfo(BestListDict.Values);
   321→            if (atker == null)
   322→                LogCommon.LogError("没有收到攻击方战力信息");
   323→            var manager = DayZ.Container.Instance.Get<IKingShotManager>();
   324→            PVEJoinerInfo defer = PVEController.Instance.GetKingShotPveDefenserInfo(manager.GameData);  //monsterid //
   325→            if (defer == null)
   326→                LogCommon.LogError("没有收到防守方战力信息");
   327→            float percent = (float)atker.power / (float)defer.power;
   328→            if (percent >= GameConfig.Property_Power_Rate1)
   329→                return EFighting.PowerCrushing;
   330→            else if (percent < GameConfig.Property_Power_Rate1 && percent >= GameConfig.Property_Power_Rate2)
   331→                return EFighting.Equal;
   332→            else
   333→                return EFighting.Insufficient;
   334→        }
