   463→        /// <summary>
   464→        /// 从世界坐标转换到fgui坐标
   465→        /// </summary>
   466→        /// <param name="wPos"></param>
   467→        /// <param name="parent"></param>
   468→        /// <returns></returns>
   469→        public Vector2 TransWorldToLocal(Vector3 wPos, GObject parent)
   470→        {
   471→            Vector2 screenPos = LevelParameters.mainCamera.WorldToScreenPoint(wPos);
   472→            //使用RT相机时需要进行坐标转化
   473→            if (LevelParameters.mainCamera.targetTexture != null)
   474→            {
   475→                var texRes = ScreenAdaptation.GetTexRes();
   476→                screenPos.y *= (float)Screen.height / texRes.y;
   477→                screenPos.x *= (float)Screen.width / texRes.x;
   478→                //宽屏x左边排除掉黑边区域
   479→                if (ScreenAdaptation.cameraRect.width < 1)
   480→                {
   481→                    float baseScreenRate = 9.0f / 16;
   482→                    float widthPercent = Screen.height * baseScreenRate / Screen.width;
   483→                    float blackPercentAtWidth = 1f - widthPercent;
   484→                    //压窄
   485→                    screenPos.x *= Screen.height * baseScreenRate / Screen.width;
   486→                    screenPos.x += blackPercentAtWidth * 0.5f * Screen.width;
   487→                }
   488→            }
   489→            screenPos.y = Screen.height - screenPos.y;
   490→            return parent.GlobalToLocal(screenPos);
   491→        }
