   533→        public void DropItems(Vector3 center, List<string> items)
   534→        {
   535→            //usedPositions.Clear();
   536→            float dropRadius = items.Count >= 20 ? 5 : 3;
   537→            foreach (var item in items)
   538→            {
   539→                var prop = item.Split(',');
   540→                if (UnityEngine.Random.value <= prop[1].floatValue())
   541→                {
   542→                    var config = GameConfig.GetDataWithTypeById<KSDropGoods>(prop[0]);
   543→                    Vector3? dropPos = GetValidDropPosition(center, dropRadius, 1f);
   544→                    if (dropPos.HasValue)
   545→                    {
   546→                        SpawnItem(config, center, dropPos.Value);
   547→                        usedPositions.Add(dropPos.Value);
   548→                    }
   549→                    else
   550→                    {
   551→                        LogCommon.LogError($"{config.Model}掉落未找到合适位置");
   552→                    }
   553→                }
   554→            }
   555→        }
   556→        private Vector3? GetValidDropPosition(Vector3 center, float dropRadius, float minItemDistance)
   557→        {
   558→            var lordHero = BaseLogic.PlayerManager.lordHero;
   559→            for (int i = 0; i < 1000; i++)
   560→            {
   561→                Vector2 randCircle = UnityEngine.Random.insideUnitCircle * dropRadius;
   562→                Vector3 randomPos = center + new Vector3(randCircle.x, 0, randCircle.y);
   563→
   564→                if (NavMesh.SamplePosition(randomPos, out NavMeshHit hit, 1.5f, NavMesh.AllAreas))
   565→                {
   566→                    Vector3 groundPos = hit.position;
   567→
   568→                    // 检查地面高度
   569→                    if (Physics.Raycast(groundPos + Vector3.up * 5f, Vector3.down, out RaycastHit groundHit, 10f, lordHero.LordParameters.GroundLayer))
   570→                    {
   571→                        Vector3 finalPos = groundHit.point;
   572→
   573→                        // 检查阻挡物
   574→                        if (Physics.CheckSphere(finalPos + Vector3.up * 0.1f, 0.3f, lordHero.LordParameters.DropObstacleLayer))
   575→                            continue;
   576→
   577→                        // 检查与其他掉落物距离
   578→                        bool tooClose = false;
   579→                        foreach (var p in usedPositions)
   580→                        {
   581→                            if (Vector3.Distance(p, finalPos) < minItemDistance)
   582→                            {
   583→                                tooClose = true;
   584→                                break;
   585→                            }
   586→                        }
   587→                        if (tooClose) continue;
   588→
   589→                        return finalPos;
   590→                    }
   591→                }
   592→            }
   593→            return null;
   594→        }
