   461→        /// <summary>
   462→        /// 敌人生成
   463→        /// </summary>
   464→        /// <param name="sWPath"></param>
   465→        /// <returns></returns>
   466→        public IEnumerator IEEnemySpawner(SWPath sWPath)
   467→        {
   468→            enemyState = EEnemyCreate.Create;
   469→            string monsterid = sWPath.monster;
   470→            string monsternumber = sWPath.monsternumber;
   471→            //获取各个怪物的id和数量
   472→            string[] id = monsterid.Split(';');
   473→            string[] numbers = monsternumber.Split(';');
   474→            
   475→            string bossid = sWPath.boss;
   476→            string bossnum = sWPath.bossnumber;
   477→            //获取各个boss的数量
   478→            string[] bossnums = bossnum.Split(';');
   479→            string[] bossids = bossid.Split(';');
   480→
   481→            for (int i = 0; i < numbers.Length; i++)
   482→            {
   483→                for (int j = 0; j < int.Parse(numbers[i]); j++)
   484→                {
   485→                    string[] randomids = id[i].Split(',');
   486→                    string randomid = randomids[UnityEngine.Random.Range(0, randomids.Length)]; //随机怪物
   487→                    SWMonster swm = DataAtlasManager.Instance.GetDataWithTypeById<SWMonster>(randomid);
   488→                    if (swm == null)
   489→                    {
   490→                        LogCommon.Log("BattleProtectScene.IEEnemySpawner" + "敌人id" + randomid + "数据不存在请检查配表");
   491→                        yield break;
   492→                    }
   493→
   494→                    CreateEnemy(swm);
   495→                    yield return new WaitForSeconds((float)sWPath.cd);
   496→                }
   497→
   498→                for (int k = 0; k < int.Parse(bossnums[i]); k++)
   499→                {
   500→                    SWMonster swm = DataAtlasManager.Instance.GetDataWithTypeById<SWMonster>(bossids[i]);
   501→                    if (swm == null)
   502→                    {
   503→                        LogCommon.Log("BattleProtectScene.IEEnemySpawner" + "bossid" + bossids[i] + "数据不存在请检查配表");
   504→                        yield break;
   505→                    }
   506→
   507→                    CreateEnemy(swm);
   508→                    yield return new WaitForSeconds((float)sWPath.cd);
   509→                }
   510→
   511→                while (!IsEmptyEnemy())//如果当前敌人被清理完成
   512→                {
   513→                    yield return new WaitForSeconds(0.1f);
   514→                }
   515→
   516→            }
   517→            enemyState = EEnemyCreate.Finsh;
   518→        }
   519→
   520→        /// <summary>
   521→        /// 判断当前关卡的敌人是否被全部清理
   522→        /// </summary>
   523→        /// <returns></returns>
   524→        public bool IsClearEnemy()
   525→        {
   526→            return enemyState == EEnemyCreate.Finsh && IsEmptyEnemy();
   527→        }
   528→        /// <summary>
   529→        /// 判断是否开始生成怪物
   530→        /// </summary>
   531→        /// <returns></returns>
   532→        public bool IsBeginEnemy()
   533→        {
   534→            return enemyState == EEnemyCreate.Create;
   535→        }
