   538→        /// <summary>
   539→        /// 创建敌人,pos敌人创建的位置
   540→        /// </summary>
   541→        /// <param name="sWMonster"></param>
   542→        public GameObject CreateEnemy(SWMonster sWMonster,Vector3 pos = default(Vector3))
   543→        {
   544→            GameObject obj = CCNodeCache.Instance.GetGameObject(sWMonster.model);
   545→            obj.transform.SetParent(newObjectParent.transform);
   546→            AddEnemyInList(obj);
   547→            //初始化敌人脚本
   548→            BattleProtectMonster battleProtectMonster = obj.GetComponent<BattleProtectMonster>();
   549→            //设置敌人攻击点
   550→            enemyArea = scene.transform.Find("EnemyAttackArea");
   551→            Vector3 left = enemyArea.Find("Left").position;
   552→            Vector3 right = enemyArea.Find("Right").position;
   553→            //计算攻击位置x轴的范围
   554→            float posxmin = left.x;
   555→            float posxmax = right.x;
   556→            float xRandom = UnityEngine.Random.Range(posxmin, posxmax);
   557→            Vector3 randomV3 = Vector3.zero;
   558→            switch ((BattleProtectMonster.EEnemyType)sWMonster.type)
   559→            {
   560→                case BattleProtectMonster.EEnemyType.Boss:
   561→                    randomV3 = new Vector3((posxmax + posxmin) / 2, left.y, left.z);
   562→                    break;
   563→                case BattleProtectMonster.EEnemyType.Nomarl:
   564→                    //随机一个攻击点，x最近，yz用第一个英雄的位置，不影响后续的攻击值
   565→                    randomV3 = new Vector3(xRandom, left.y, left.z);
   566→                    break;
   567→            }
   568→
   569→            battleProtectMonster.InitMonster(randomV3, sWMonster);
   570→
   571→            //初始敌人位置
   572→            int index = UnityEngine.Random.Range(0, enemySpawnerPos.Length);
   573→
   574→            if (pos != default(Vector3))
   575→                obj.transform.position = pos;
   576→            else
   577→            {
   578→                switch (battleProtectMonster.GetState())
   579→                {
   580→                    case BattleProtectMonster.EEnemyType.Boss:
   581→                        obj.transform.position = enemySpawnerPos[enemySpawnerPos.Length / 2].position;
   582→                        break;
   583→                    case BattleProtectMonster.EEnemyType.Nomarl:
   584→                        obj.transform.position = enemySpawnerPos[index].position;
   585→                        break;
   586→                }
   587→            }
   588→
   589→            return obj;
   590→        }
